const state={authenticated:true,authMode:'login',view:'lobby',roomTab:'chat',roomId:null,sessionStatus:'idle',voice:'disconnected',network:'disconnected',muted:false,deafened:false,speaking:false,volume:80,friendFilter:'online',friendQuery:'',friends:['阿岚','青禾','北屿','苏叶'],incomingRequests:['洛川'],outgoingRequests:[],invites:[],modal:null,toast:'',groupId:'expedition',role:'owner',memberVolumes:{},drafts:{room:{},group:{}},chatScroll:{room:{},group:{}},joinedAt:null,settingsTab:'voice',settings:{speaking:true,recover:true,inputDevice:'默认麦克风（模拟）',outputDevice:'头戴式耳机（模拟）'},nextId:10};
Object.defineProperty(state,'joined',{get(){return ['joining','active'].includes(state.sessionStatus)}});
window.state=state;window.rooms=rooms;window.groups=groups;
const me='林墨';
const currentRoom=()=>rooms.find(r=>r.id===state.roomId)||null;
const currentGroup=()=>groups.find(g=>g.id===state.groupId)||groups[0];
const roomMembers=r=>r?.members||[];
const myMember=r=>roomMembers(r).find(m=>m.name===me);
const personStatus=n=>{const p=people[n];if(!p?.online)return n==='洛川'?'20 分钟前在线':'离线';const r=rooms.find(r=>r.id===p.roomId);return r?`${r.name} · ${r.game}`:'在线'};
const onlineFriends=()=>state.friends.filter(n=>people[n]?.online);
const timeNow=()=>new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false});
const canModerate=()=>['owner','admin'].includes(state.role);
function toast(text){state.toast=text;renderToast();clearTimeout(toast.timer);toast.timer=setTimeout(()=>{state.toast='';renderToast()},2800)}
function renderToast(){document.getElementById('toast').innerHTML=state.toast?`<div class="toast">${esc(state.toast)}</div>`:''}
function openModal(title,desc,body,actions=''){state.modal={title,desc,body,actions};renderModal()}
function closeModal(){state.modal=null;renderModal()}
function renderModal(){const m=state.modal;document.getElementById('modal').innerHTML=m?`<div class="modal-backdrop" data-action="backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><div><h2 id="modal-title">${m.title}</h2><p>${m.desc||''}</p></div><button class="icon-button" data-action="modal-close" aria-label="关闭">${icon('close',18)}</button></div><div>${m.body}</div>${m.actions?`<div class="modal-actions">${m.actions}</div>`:''}</section></div>`:''}
function topbar(){return `<header class="titlebar"><div class="brand"><span class="brand-mark"></span><span class="brand-name">织界<small>WEAVORA</small></span></div><span class="window-title">和喜欢的人，玩同一个世界</span><div class="top-actions"><span class="connection-pill"><i class="status-dot"></i>原型模拟数据</span><div class="window-controls"><button data-action="window-control" data-window="minimize" aria-label="最小化">—</button><button data-action="window-control" data-window="maximize" aria-label="最大化">□</button><button data-action="window-control" data-window="close" aria-label="关闭">×</button></div></div></header>`}
function rail(){const item=(view,ico,label)=>`<button class="nav-item ${state.view===view||(view==='groups'&&state.view==='groupChat')?'active':''}" data-action="nav" data-view="${view}" aria-label="${label}">${icon(ico)}<span>${label}</span></button>`;return `<aside class="rail"><nav aria-label="主导航">${item('lobby','home','大厅')}${item('friends','users','好友')}${item('groups','messages','群组')}<div class="rail-separator"></div><button class="nav-item" data-action="create-room" aria-label="创建房间">${icon('plus')}<span>创建</span></button></nav><div class="rail-bottom"><button class="nav-item" data-action="help" aria-label="联机帮助">${icon('help')}</button><button class="nav-item ${state.view==='settings'?'active':''}" data-action="nav" data-view="settings" aria-label="设置">${icon('settings')}</button><button class="mini-me" data-action="profile" aria-label="林墨的账号">林</button></div></aside>`}
function statusChip(type,value){if(value==='connected')return `<span class="status-chip good"><i class="status-dot"></i>${type==='voice'?'语音已连接':'LAN 已连接'}</span>`;if(['connecting','retrying'].includes(value))return `<span class="status-chip">${type==='voice'?'语音':'网络'}连接中…</span>`;return `<span class="status-chip">${type==='voice'?'语音':'网络'}未连接 <button class="text-button" data-action="${type==='voice'?'voice':'network'}-retry">重试</button></span>`}
function voiceDock(){if(!state.joined)return '';const r=currentRoom();return `<div class="voice-dock"><button class="voice-now" data-action="open-room" data-room="${r.id}" style="border:0;background:transparent;color:inherit;text-align:left;padding:0"><span class="voice-room-icon">${icon('headphones')}</span><span><strong>${esc(r.name)}</strong><small>${state.sessionStatus==='joining'?'正在加入房间，双通道独立连接':`${state.voice==='connected'?'语音已连接':'语音连接中'} · ${state.network==='connected'?'虚拟网络已连接':'虚拟网络连接中'}`}</small></span></button><div class="voice-controls">${state.speaking&&state.settings.speaking?'<div class="wave" aria-label="正在发言"><i></i><i></i><i></i><i></i><i></i></div>':''}<button class="voice-button ${state.muted?'off':''}" data-action="toggle-mute" title="${state.muted?'取消静音':'麦克风静音'}">${icon(state.muted?'micOff':'mic')}<span>${state.muted?'已静音':state.speaking?'发言中':'已开麦'}</span></button><button class="voice-button ${state.deafened?'off':''}" data-action="toggle-deafen" title="${state.deafened?'恢复接收':'关闭接收'}">${icon('headphones')}</button><button class="voice-button" data-action="audio-settings" title="语音设置">${icon('settings')}</button><button class="voice-button leave" data-action="leave-room" title="离开房间">${icon('phoneOff')}</button></div><div class="voice-right">${statusChip('network',state.network)}</div></div>`}
function friendItem(name,status=personStatus(name)){return `<div class="friend-item"><button data-action="friend-profile" data-name="${name}" style="display:flex;align-items:center;gap:10px;flex:1;min-width:0;border:0;background:transparent;color:inherit;text-align:left;padding:0">${avatar(name)}<span class="friend-copy"><strong>${name}</strong><small>${esc(status)}</small></span></button><button class="icon-button" data-action="invite-friend" data-name="${name}" title="邀请组队">${icon('plus',15)}</button></div>`}
function aside(){const online=onlineFriends();return `<aside class="right-panel"><div class="panel-title"><h2>在线好友</h2><span class="count-badge">${online.length} 在线</span></div><div class="friend-list">${online.map(n=>friendItem(n)).join('')||'<div class="empty-state">暂无在线好友</div>'}</div><button class="button ghost" style="width:100%;margin-top:10px" data-action="nav" data-view="friends">查看全部好友 ${icon('arrow',14)}</button><div class="aside-divider"></div><div class="tip-card"><strong>联机小贴士</strong><br>进入房间后，在「联机」页复制实际游戏主机成员虚拟 IP，再回到游戏中直接连接。</div></aside>`}
function roomCard(r){const isCurrent=state.joined&&r.id===state.roomId;return `<article class="room-card"><div class="room-cover ${r.cover}"><span class="game-chip">${esc(r.game)}</span><span class="room-capacity">${r.members.length} / 16</span></div><div class="room-body"><div class="room-title-row"><h3>${esc(r.name)}</h3><span class="status-dot" title="${r.open?'开放加入':'暂停加入'}"></span></div><p>${esc(r.desc)} · ${r.open?'进行中':'暂停加入'}</p><div class="room-footer"><div class="avatar-stack">${r.members.map(m=>avatar(m.name)).join('')}</div><button class="join-arrow" data-action="${isCurrent?'open-room':'join-room'}" data-room="${r.id}" aria-label="${isCurrent?'回到':'加入'} ${esc(r.name)}">${icon('arrow',16)}</button></div></div></article>`}
function activeHero(){if(!state.joined)return '';const r=currentRoom();return `<section class="hero"><div class="hero-copy"><span class="live-label"><i></i> YOUR PARTY IS LIVE</span><h2>${esc(r.name)}</h2><span class="hero-game">${esc(r.game)} · ${esc(r.desc)}</span><div class="hero-meta"><div class="avatar-stack">${r.members.map(m=>avatar(m.name)).join('')}</div><span>${r.members.length} 位玩家正在房间里</span></div><div class="hero-cta"><button class="button primary" data-action="open-room" data-room="${r.id}">回到房间 ${icon('arrow',15)}</button><span class="link-note">${state.sessionStatus==='joining'?'正在建立连接':'已加入 · 可跨页面保持语音'}</span></div></div><div class="network-visual" style="display:flex;align-items:center;justify-content:center"><div style="text-align:center"><div class="network-core" style="position:static;margin:0 auto 18px">${icon('network',28)}</div><strong>语音与虚拟网络独立连接</strong><p class="link-note" style="margin-top:10px">一项异常时，另一项可以继续使用</p></div></div></section>`}
function lobby(){return `<div class="content-grid"><main class="main-scroll"><div class="page-heading"><div><div class="eyebrow">PLAYER LOBBY · 玩家大厅</div><h1>别等开局，先聚在一起。</h1><p>语音、聊天和虚拟局域网，在一个房间里就绪。</p></div><div class="heading-actions"><button class="button" data-action="join-code">加入房间</button><button class="button primary" data-action="create-room">${icon('plus',16)} 快速组队</button></div></div>${activeHero()}<div class="section-head"><div><h2>${state.joined?'发现其他房间':'选择一个房间，准备开局'}</h2><p>房间人数、开放状态与成员信息来自同一份模拟房间数据。</p></div><button class="text-button" data-action="create-room">创建新房间 +</button></div><div class="room-grid">${rooms.map(roomCard).join('')}</div><p class="prototype-note">高保真交互原型 · 所有玩家、消息与连接状态均为模拟数据</p></main>${aside()}</div>`}
function playerTile(m){const r=currentRoom(),muted=m.name===me?state.muted:!!m.muted;return `<article class="player-tile ${m.speaking&&state.settings.speaking?'speaking':''}">${m.name===r.host?'<span class="host-tag">HOST</span>':m.name===me?'<span class="host-tag">YOU</span>':''}<button class="icon-button tile-more" data-action="player-settings" data-name="${m.name}" aria-label="${m.name} 的设置">${icon('more',17)}</button>${avatar(m.name)}<div class="player-name"><div><strong>${m.name}${m.name===me?'（你）':''}</strong><small>${m.voice!=='connected'?'语音连接中':muted?'麦克风已关闭':m.speaking?'正在说话':'语音已连接'}</small></div><span class="player-state ${muted?'muted':''}">${icon(muted?'micOff':'mic',15)}</span></div></article>`}
function mediaPreview(media){if(!media)return '';return media.type==='video'?`<video class="message-media" src="${esc(media.url)}" controls preload="metadata" aria-label="${esc(media.name)}"></video>`:`<img class="message-media" src="${esc(media.url)}" alt="${esc(media.name)}">`}
function messageHtml(m,scope){const deleted=m.deleted;return `<div class="message ${scope==='group'&&m.user===me?'own':''}" data-message-id="${m.id}">${avatar(m.user)}<div class="message-content"><div class="message-meta"><strong>${esc(m.user)}</strong><time>${m.time}</time>${!deleted&&(m.user===me||canModerate())?`<button class="icon-button message-more" data-action="delete-message" data-scope="${scope}" data-id="${m.id}" aria-label="删除消息">${icon('more',15)}</button>`:''}</div>${deleted?'<div class="message-text">此消息已被删除</div>':`${m.text?`<div class="message-text">${esc(m.text)}</div>`:''}${mediaPreview(m.media)}`}</div></div>`}
function chatPanel(){const r=currentRoom();return `<div class="chat-scroll"><div class="chat-day">房间消息长期保留 · 支持图片与视频</div>${r.messages.map(m=>messageHtml(m,'room')).join('')}</div><form class="chat-compose" data-form="room-message"><button class="icon-button" type="button" data-action="attach-media" data-scope="room" aria-label="发送图片或视频">${icon('plus',17)}</button><input id="room-message-input" data-input="room-draft" value="${esc(state.drafts.room[r.id]||'')}" aria-label="房间消息" placeholder="发消息给房间里的队友…" autocomplete="off"><button class="icon-button" type="submit" aria-label="发送">${icon('send',16)}</button></form>`}
function networkPanel(){const r=currentRoom();if(state.network!=='connected')return `<div class="network-panel"><div class="network-hero">${statusChip('network',state.network)}<h3>正在准备虚拟局域网</h3><p>地址尚未分配，不会在连接成功前展示可用 IP。</p></div></div>`;return `<div class="network-panel"><div class="network-hero">${statusChip('network',state.network)}<h3>你们已经在同一个网络里</h3><p>织界房主不一定是游戏内主机。请复制实际创建游戏世界的成员地址。</p></div><div class="step-list"><div class="step"><span class="step-num">1</span><div><strong>确认谁在游戏里创建主机</strong><p>由队友约定，织界不会自动猜测游戏主机。</p></div></div><div class="step"><span class="step-num">2</span><div><strong>复制该成员的虚拟 IP</strong><p>所有当前房间成员的地址都列在下方。</p></div></div><div class="step"><span class="step-num">3</span><div><strong>在游戏里直接连接</strong><p>粘贴地址；如需端口，按游戏规则补充。</p></div></div></div><div class="member-ip-heading"><strong>成员虚拟 IP</strong><span>${r.members.length} 个可用地址</span></div><div class="member-ip-list">${r.members.map(memberIpRow).join('')}</div><p class="network-note">“你”标记的是自己的地址。仅连接本房间成员的本机服务；不代理普通互联网流量，不转发物理局域网其他设备。所有地址均为原型模拟数据。</p><button class="button ghost small" style="margin-top:14px" data-action="network-help">连接失败怎么办？</button></div>`}
function memberIpRow(m){return `<div class="member-ip-row">${avatar(m.name)}<div class="member-ip-copy"><strong>${esc(m.name)}${m.name===me?'（你）':''}</strong><span class="ip-address">${m.ip}</span></div><button class="copy-button" data-action="copy-ip" data-ip="${m.ip}" data-name="${esc(m.name)}" aria-label="复制 ${esc(m.name)} 的虚拟 IP">${icon('copy',12)} 复制</button></div>`}
function membersPanel(){const r=currentRoom();return `<div class="network-panel"><div class="panel-title"><h2>房间成员</h2><span class="count-badge">${r.members.length} / 16</span></div>${r.members.map(m=>friendItem(m.name,`${m.name===r.host?'房主 · ':''}${m.ip}`)).join('')}<button class="button primary" style="width:100%;margin-top:16px" data-action="invite-friend">${icon('userPlus',15)} 邀请队友</button></div><div></div>`}
function roomView(){const r=currentRoom();if(!r)return lobby();return `<div class="room-layout"><main class="room-stage"><div class="room-top"><div class="room-heading"><button class="back-button" data-action="nav" data-view="lobby" aria-label="返回大厅">${icon('back',17)}</button><div><h1>${esc(r.name)}</h1><p>${esc(r.game)} · ${esc(r.desc)} · ${r.members.length} / 16</p></div></div><div class="room-flags">${statusChip('voice',state.voice)}${statusChip('network',state.network)}<button class="icon-button" data-action="room-settings" title="房间设置">${icon('settings',17)}</button></div></div><div class="party-grid">${r.members.map(playerTile).join('')}<article class="player-tile empty-player"><button data-action="invite-friend">${icon('userPlus',24)}<span>邀请队友</span></button></article></div><p class="prototype-note">说话状态与网络信息均为模拟 · 最多 16 个不同账号</p></main><aside class="room-side"><div class="side-tabs">${[['chat','聊天'],['network','联机'],['members',`成员 ${r.members.length}`]].map(([id,label])=>`<button class="side-tab ${state.roomTab===id?'active':''}" data-action="room-tab" data-tab="${id}">${label}</button>`).join('')}</div>${state.roomTab==='chat'?chatPanel():state.roomTab==='network'?networkPanel():membersPanel()}</aside></div>`}
function friendsView(){const query=state.friendQuery.trim().toLowerCase();const filtered=state.friends.filter(n=>(state.friendFilter==='all'||people[n].online)&&(!query||n.toLowerCase().includes(query)||people[n].id.toLowerCase().includes(query)));return `<main class="main-scroll"><div class="center-panel"><div class="page-heading"><div><div class="eyebrow">FRIENDS · 好友</div><h1>下次开局，不用再找人。</h1><p>看看谁在线，直接邀请进房。好友关系不自动授予群组权限。</p></div><button class="button primary" data-action="add-friend">${icon('userPlus',16)} 添加好友</button></div><div class="filter-row"><input class="search-field" data-input="friend-search" value="${esc(state.friendQuery)}" placeholder="搜索昵称或账号 ID" aria-label="搜索好友"><div class="segmented"><button class="${state.friendFilter==='online'?'active':''}" data-action="friend-filter" data-filter="online">在线 ${onlineFriends().length}</button><button class="${state.friendFilter==='all'?'active':''}" data-action="friend-filter" data-filter="all">全部 ${state.friends.length}</button><button data-action="friend-requests">待处理 <span style="color:var(--accent)">${state.incomingRequests.length}</span></button></div></div><section class="friends-table">${filtered.length?filtered.map(n=>`<div class="friend-row">${avatar(n)}<div class="friend-copy"><strong>${n}</strong><small>${personStatus(n)} · ${people[n].id}</small></div><button class="button ghost" data-action="invite-friend" data-name="${n}">${icon('plus',14)} 邀请组队</button><button class="icon-button" data-action="friend-profile" data-name="${n}">${icon('more',17)}</button></div>`).join(''):'<div class="empty-state">没有找到匹配的好友，可尝试完整昵称或账号 ID。</div>'}</section></div></main>`}
function groupsView(){return `<main class="main-scroll"><div class="center-panel"><div class="page-heading"><div><div class="eyebrow">GROUPS · 私密群组</div><h1>朋友常在，热闹不散。</h1><p>长期保留聊天与房间，只通过私密邀请加入。</p></div><button class="button primary" data-action="create-group">${icon('plus',16)} 创建群组</button></div><div class="group-grid">${groups.map(g=>`<button class="group-card" data-action="open-group" data-group="${g.id}"><div class="group-card-top"><span class="group-icon">${g.icon}</span>${icon('arrow',17)}</div><h3>${esc(g.name)}</h3><p>${g.members.length} 位成员 · ${g.roomIds.length} 个游戏房间</p><div class="group-card-foot"><span>私密群组</span><span>进入聊天 →</span></div></button>`).join('')}</div></div></main>`}
function groupChatView(){const g=currentGroup(),online=g.members.filter(n=>people[n]?.online).length,groupRooms=rooms.filter(r=>g.roomIds.includes(r.id));return `<div class="group-chat"><header class="group-chat-head"><button class="back-button" data-action="nav" data-view="groups" aria-label="返回群组列表">${icon('back',16)}</button><div><h1>${esc(g.name)}</h1><p>${g.members.length} 位成员 · ${online} 人在线 · ${esc(g.desc||'私密群组')}</p></div><button class="button ghost small" style="margin-left:auto" data-action="group-manage">群组管理</button></header><div class="group-chat-content"><div class="group-chat-body"><div class="chat-day">群组消息会长期保留 · 支持图片与视频</div>${g.messages.map(m=>messageHtml(m,'group')).join('')}</div><aside class="group-room-list"><div class="panel-title"><h2>游戏房间</h2><span class="count-badge">${groupRooms.length}</span></div><p>和群友从聊天直接进入同一局。</p>${groupRooms.map(r=>`<article class="group-room-card"><span class="game-chip-static">${esc(r.game)}</span><h3>${esc(r.name)}</h3><div><span>${r.members.length} / 16 · ${r.open?'进行中':'暂停加入'}</span><button class="join-arrow" data-action="${state.joined&&state.roomId===r.id?'open-room':'join-room'}" data-room="${r.id}" aria-label="${state.joined&&state.roomId===r.id?'回到':'加入'} ${esc(r.name)}">${icon('arrow',15)}</button></div></article>`).join('')||'<div class="group-room-empty">还没有游戏房间<br>创建后会显示在这里。</div>'}<button class="button ghost small" data-action="create-room">${icon('plus',13)} 创建群房间</button></aside></div><form class="group-compose" data-form="group-message"><button class="icon-button" type="button" data-action="attach-media" data-scope="group" aria-label="发送图片或视频">${icon('plus',17)}</button><input id="group-message-input" data-input="group-draft" value="${esc(state.drafts.group[g.id]||'')}" placeholder="发消息到 ${esc(g.name)}，或分享图片与视频" aria-label="群组消息" autocomplete="off"><button class="button primary" type="submit">${icon('send',15)} 发送</button></form></div>`}
function voiceSettingsPanel(){return `<section class="settings-card"><h2>语音设备</h2><div class="setting-row"><div><strong>输入设备</strong><small>选择队友听到的麦克风</small></div><select data-change="input-device" aria-label="输入设备"><option ${state.settings.inputDevice==='默认麦克风（模拟）'?'selected':''}>默认麦克风（模拟）</option><option ${state.settings.inputDevice==='USB 麦克风（模拟）'?'selected':''}>USB 麦克风（模拟）</option></select></div><div class="setting-row"><div><strong>输出设备</strong><small>选择游戏语音播放设备</small></div><select data-change="output-device" aria-label="输出设备"><option ${state.settings.outputDevice==='头戴式耳机（模拟）'?'selected':''}>头戴式耳机（模拟）</option><option ${state.settings.outputDevice==='默认扬声器（模拟）'?'selected':''}>默认扬声器（模拟）</option></select></div><div class="setting-row"><div><strong>总音量 · <span id="master-volume-label">${state.volume}%</span></strong><small>只调整本地接收音量</small></div><input class="setting-range" type="range" min="0" max="100" value="${state.volume}" data-input="volume" aria-label="总音量"></div><div class="setting-row"><div><strong>麦克风测试</strong><small>原型不会采集或播放真实音频</small></div><button class="button small" data-action="device-test">测试设备</button></div></section><section class="settings-card"><h2>语音体验</h2><div class="setting-row"><div><strong>说话状态提示</strong><small>在头像周围显示音量反馈</small></div><button class="toggle ${state.settings.speaking?'on':''}" data-action="toggle-setting" data-setting="speaking" aria-label="切换说话状态提示" aria-pressed="${state.settings.speaking}"></button></div><div class="setting-row"><div><strong>自动恢复连接</strong><small>网络恢复后重连，保留期内恢复原虚拟 IP</small></div><button class="toggle ${state.settings.recover?'on':''}" data-action="toggle-setting" data-setting="recover" aria-label="切换自动恢复" aria-pressed="${state.settings.recover}"></button></div><div class="modal-note">语音设置只影响本地体验，不会中断虚拟局域网。设备权限拒绝、拔出和连接失败应分别提示。</div></section>`}
function accountSettingsPanel(){return `<section class="settings-card"><h2>账号与设备</h2><div class="modal-note">邮箱已验证；多端登录不等于多设备同时活动。</div><div class="setting-row"><div><strong>林墨</strong><small>demo@example.test · 已验证</small></div><span class="status-chip good">账号有效</span></div><div class="setting-row"><div><strong>此电脑</strong><small>Windows · 当前活动设备</small></div><span class="status-chip">活动中</span></div><div class="setting-row"><div><strong>另一台电脑</strong><small>macOS · 已登录，未入房</small></div><button class="button small" data-action="device-transfer">转移活动</button></div></section><section class="settings-card"><h2>活动设备规则</h2><p class="settings-description">转移活动前会预检目标设备；成功后旧设备的房间语音、虚拟网络与活动资格立即失效。确认操作仍使用独立对话框，避免误触。</p></section>`}
function supportSettingsPanel(){return `<section class="settings-card"><h2>安装与支持矩阵</h2><div class="modal-note">当前所有平台与游戏均为「候选 / 未验证」。原型不能证明安装、语音、虚拟网络或游戏兼容通过。</div><div class="setting-row"><div><strong>Windows 10 / 11 x64</strong><small>NSIS · 权限条件待验证</small></div><span class="status-chip">未验证</span></div><div class="setting-row"><div><strong>macOS 13+</strong><small>Intel / Apple Silicon</small></div><span class="status-chip">未验证</span></div><div class="setting-row"><div><strong>Ubuntu 22.04 / 24.04</strong><small>x86_64 · 桌面环境待验证</small></div><span class="status-chip">未验证</span></div></section><section class="settings-card"><h2>验证状态说明</h2><p class="settings-description">只有真实安装与实机走查完成后，对应平台才会更新为已验证；候选支持不代表兼容承诺。</p></section>`}
function settingsView(){const tab=state.settingsTab,content=tab==='account'?accountSettingsPanel():tab==='support'?supportSettingsPanel():voiceSettingsPanel();return `<main class="main-scroll"><div class="center-panel"><div class="page-heading"><div><div class="eyebrow">PREFERENCES · 设置</div><h1>按你的方式，舒服地玩。</h1><p>账号、语音和连接偏好只保存在本机。</p></div></div><div class="settings-grid"><nav class="settings-menu" role="tablist" aria-label="设置分类"><button role="tab" aria-selected="${tab==='voice'}" class="${tab==='voice'?'active':''}" data-action="settings-tab" data-tab="voice">语音与设备</button><button role="tab" aria-selected="${tab==='account'}" class="${tab==='account'?'active':''}" data-action="account-settings">账号与设备</button><button role="tab" aria-selected="${tab==='support'}" class="${tab==='support'?'active':''}" data-action="support-matrix">安装与支持</button><button data-action="logout">退出登录</button></nav><div class="settings-content" role="tabpanel" aria-label="${tab==='account'?'账号与设备':tab==='support'?'安装与支持':'语音与设备'}">${content}</div></div></div></main>`}
function authView(){let body='';if(state.authMode==='login')body=`<div class="field"><label>邮箱</label><input id="email" type="email" value="demo@example.test"></div><div class="field"><label>密码</label><input type="password" value="prototype-only"></div><button class="button primary" style="width:100%" data-action="login">进入玩家大厅 ${icon('arrow',15)}</button><div class="auth-links"><button data-action="auth-mode" data-mode="register">注册账号</button><button data-action="auth-mode" data-mode="forgot">找回密码</button></div>`;else if(state.authMode==='register')body=`<div class="field"><label>邮箱</label><input placeholder="name@example.com"></div><div class="field"><label>设置密码</label><input type="password"></div><button class="button primary" style="width:100%" data-action="register">发送模拟验证码</button><div class="auth-links"><button data-action="auth-mode" data-mode="login">返回登录</button></div>`;else if(state.authMode==='verify')body=`<div class="modal-note" style="margin-bottom:16px">模拟邮件已发送，真实邮件投递不在本原型验证范围。</div><div class="field"><label>6 位验证码</label><input maxlength="6" placeholder="000000"></div><button class="button primary" style="width:100%" data-action="verify">验证并进入大厅</button>`;else body=`<div class="modal-note" style="margin-bottom:16px">仅通过已验证邮箱找回，不提供人工绕过入口。</div><div class="field"><label>已验证邮箱</label><input placeholder="name@example.com"></div><button class="button primary" style="width:100%" data-action="forgot">发送模拟重置邮件</button><div class="auth-links"><button data-action="auth-mode" data-mode="login">返回登录</button></div>`;return `<div class="auth"><section class="auth-card"><div class="brand"><span class="brand-mark"></span><span class="brand-name">织界<small>WEAVORA</small></span></div><h1>${state.authMode==='login'?'欢迎回来，玩家。':state.authMode==='register'?'创建你的玩家账号':'验证你的身份'}</h1><p>和朋友在同一个世界，随时开局。</p>${body}<p class="prototype-note">交互原型 · 输入不会发送或保存</p></section></div>`}
function render(){const app=document.getElementById('app');if(!state.authenticated){app.innerHTML=authView();renderModal();return}let content=state.view==='room'?roomView():state.view==='friends'?friendsView():state.view==='groups'?groupsView():state.view==='groupChat'?groupChatView():state.view==='settings'?settingsView():lobby();app.innerHTML=`<div class="app">${topbar()}<div class="workspace">${rail()}<div class="content-shell ${state.joined?'':'no-voice'}">${content}${voiceDock()}</div></div></div>`;renderModal();const roomChat=document.querySelector('.chat-scroll'),groupChat=document.querySelector('.group-chat-body');if(roomChat)roomChat.scrollTop=state.chatScroll.room[state.roomId]||0;if(groupChat)groupChat.scrollTop=state.chatScroll.group[state.groupId]||0}
function scrollChatToBottom(scope){setTimeout(()=>{const el=document.querySelector(scope==='room'?'.chat-scroll':'.group-chat-body'),id=scope==='room'?state.roomId:state.groupId;if(!el||!id)return;el.scrollTop=el.scrollHeight;state.chatScroll[scope][id]=el.scrollTop},0)}
function createRoomModal(){openModal('开一个新房间','房间会长期保存，结束一次活动不会删除配置。',`<div class="field"><label>房间名称</label><input id="new-room-name" value="周五快乐局"></div><div class="field-row"><div class="field"><label>游戏名称</label><input id="new-room-game" value="手动输入游戏名"></div><div class="field"><label>所属群组</label><select id="new-room-group">${groups.map(g=>`<option value="${g.id}">${esc(g.name)}</option>`).join('')}</select></div></div><div class="modal-note">创建后进入房间，语音与虚拟网络分别连接。初版固定最多 16 人。</div>`,`<button class="button" data-action="modal-close">取消</button><button class="button primary" data-action="confirm-create-room">创建并进入</button>`)}
function joinModal(id){const r=rooms.find(r=>r.id===id);if(!r.open){toast('房间已暂停加入，现有成员不受影响。');return}openModal(`加入「${esc(r.name)}」`,'语音与虚拟局域网将分别开始连接。',`<div class="field"><label>房间密码</label><input type="password" placeholder="本原型不校验密码"></div><div class="modal-note">系统会校验群籍、开放状态、16 人容量和单设备活动资格。${state.joined?'切房成功前保留当前活动。':''}</div>`,`<button class="button" data-action="modal-close">取消</button><button class="button primary" data-action="confirm-join" data-room="${r.id}">${state.joined?'切换房间':'加入并连接'} ${icon('arrow',14)}</button>`)}
function joinRoom(id){const old=currentRoom(),r=rooms.find(r=>r.id===id);if(old&&old.id!==id)old.members=old.members.filter(m=>m.name!==me);state.roomId=id;if(!r.members.some(m=>m.name===me)){let host=10;while(r.members.some(m=>m.ip===`10.66.${rooms.indexOf(r)}.${host}`))host++;const ip=`10.66.${rooms.indexOf(r)}.${host}`;r.members.push({name:me,ip,voice:'connecting',muted:state.muted})}const mine=myMember(r);if(mine)mine.muted=state.muted;state.sessionStatus='joining';state.voice='connecting';state.network='connecting';state.joinedAt=Date.now();state.view='room';state.roomTab='network';closeModal();render();setTimeout(()=>{if(state.roomId!==id||state.sessionStatus!=='joining')return;state.sessionStatus='active';state.voice='connected';state.network='connected';myMember(r).voice='connected';render();toast('语音与虚拟局域网已分别连接（模拟）。')},800)}
function leaveRoom(){const r=currentRoom();if(r)r.members=r.members.filter(m=>m.name!==me);state.sessionStatus='idle';state.voice='disconnected';state.network='disconnected';state.speaking=false;state.roomId=null;state.joinedAt=null;state.view='lobby';closeModal();render();toast('已离开房间，持久配置仍保留。')}
function helpModal(network=false){openModal(network?'虚拟网络连接帮助':'三步，进入同一个世界','不依赖广播发现，也不代理普通互联网流量。','<div class="step-list"><div class="step"><span class="step-num">1</span><div><strong>确认房间资格有效</strong><p>房间未暂停、人数未满，账号与设备活动资格正常。</p></div></div><div class="step"><span class="step-num">2</span><div><strong>分别检查语音与网络</strong><p>两项独立连接，一项失败时可单独重试。</p></div></div><div class="step"><span class="step-num">3</span><div><strong>复制实际游戏主机成员 IP，在游戏内直接连接</strong><p>地址冲突、系统权限不足与连接失败会给出不同提示。</p></div></div></div>',`<button class="button primary" data-action="modal-close">知道了</button>`)}
function groupManageModal(){openModal('群组管理','社交与治理分离；敏感操作按执行时资格重新校验。',`<div class="field"><label>模拟当前身份（仅用于权限走查）</label><select data-change="role"><option value="owner" ${state.role==='owner'?'selected':''}>群主</option><option value="admin" ${state.role==='admin'?'selected':''}>管理员</option><option value="member" ${state.role==='member'?'selected':''}>普通成员</option></select></div><div class="setting-row"><div><strong>成员与角色</strong><small>邀请、撤销、转让与成员资格</small></div><button class="button small" data-action="manage-members">管理</button></div>${canModerate()?`<div class="setting-row"><div><strong>只读管理记录</strong><small>只追加，不可修改、删除或清空</small></div><button class="button small" data-action="audit">查看</button></div>`:''}${state.role==='owner'?'<div class="setting-row"><div><strong>群主治理</strong><small>退出前须完成转让或解散</small></div><button class="button small danger" data-action="owner-actions">危险操作</button></div>':''}`,`<button class="button primary" data-action="modal-close">完成</button>`)}
function inviteModal(name){const choices=name?[name]:state.friends;openModal('邀请队友','对方接受后加入房间，好友关系本身不授予群权限。',`<div class="field"><label>选择好友</label><select id="invite-name">${choices.map(n=>`<option>${n}</option>`).join('')}</select></div><div class="field"><label>目标房间</label><select id="invite-room">${rooms.map(r=>`<option value="${r.id}" ${r.id===state.roomId?'selected':''}>${esc(r.name)}</option>`).join('')}</select></div><div class="field"><label>附一句话（可选）</label><input value="来一起玩，房间已经开好了。"></div>`,`<button class="button" data-action="modal-close">取消</button><button class="button primary" data-action="confirm-invite">发送邀请</button>`)}
function mediaModal(scope){state.pendingMedia=null;openModal('分享图片或视频','选择本机文件，确认预览后发送；原型不会上传文件。',`<div class="field"><label>图片 / 视频</label><input id="media-file" type="file" accept="image/*,video/*" data-change="media-file"></div><div id="media-preview" class="media-preview"><span>尚未选择文件</span></div><div class="field" style="margin-top:16px"><label>附一句话（可选）</label><input id="media-caption" placeholder="说说这个精彩瞬间…"></div>`,`<button class="button" data-action="modal-close">取消</button><button class="button primary" data-action="confirm-media" data-scope="${scope}">发送</button>`)}
function roomSettingsModal(){const r=currentRoom();openModal('房间设置','持久配置与临时活动分离。',`<div class="field"><label>房间名称</label><input id="edit-room-name" value="${esc(r.name)}"></div><div class="field"><label>游戏名</label><input id="edit-room-game" value="${esc(r.game)}"></div><div class="field"><label>房主</label><select id="edit-room-host">${r.members.map(m=>`<option ${m.name===r.host?'selected':''}>${m.name}</option>`).join('')}</select></div><div class="modal-note">当前${r.open?'开放加入':'暂停加入'}。暂停不清退现有成员；结束活动保留配置。</div>`,`<button class="button" data-action="pause-room">${r.open?'暂停加入':'重新开放'}</button><button class="button danger" data-action="end-room">结束活动</button><button class="button primary" data-action="save-room">保存</button>`)}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;
 if(a==='nav'){state.view=b.dataset.view;state.modal=null;render()}
 else if(a==='window-control'){const action=b.dataset.window;if(action==='close')openModal('关闭织界？','浏览器原型不会关闭真实窗口；正式桌面客户端将在此退出应用。','<div class="modal-note">若已加入房间，正式退出前应明确提示语音与虚拟局域网将断开。</div>',`<button class="button primary" data-action="modal-close">继续使用</button>`);else toast(`${action==='minimize'?'最小化':'最大化'}由正式桌面客户端执行，浏览器原型不操作真实窗口。`)}
 else if(a==='open-room'){const id=b.dataset.room;if(state.joined&&id===state.roomId){state.view='room';state.roomTab='chat';closeModal();render()}else joinModal(id)}
 else if(a==='join-room'){joinModal(b.dataset.room)}
 else if(a==='confirm-join'){joinRoom(b.dataset.room)}
 else if(a==='create-room'){createRoomModal()}
 else if(a==='confirm-create-room'){const name=document.getElementById('new-room-name').value.trim();if(!name){toast('请填写房间名称。');return}const id='room-'+state.nextId++,groupId=document.getElementById('new-room-group').value;rooms.push({id,name,game:document.getElementById('new-room-game').value.trim()||'未指定游戏',desc:'好友组队',cover:'cubes',groupId,host:me,open:true,members:[],messages:[]});groups.find(g=>g.id===groupId).roomIds.push(id);joinRoom(id)}
 else if(a==='join-code'){openModal('加入游戏房间','输入朋友分享的房间邀请码。','<div class="field"><label>邀请码</label><input id="join-code" value="WV-7K2M-9P" autocomplete="off"></div><div class="modal-note">重复加入会幂等处理；第 17 个不同账号或暂停加入会被明确拒绝。</div>',`<button class="button" data-action="modal-close">取消</button><button class="button primary" data-action="confirm-join-code">加入房间</button>`)}
 else if(a==='confirm-join-code'){const code=document.getElementById('join-code').value.trim().toUpperCase(),roomId={'WV-7K2M-9P':'weekend','WV-STAR-3K':'star'}[code];if(!roomId){toast('邀请码无效，请检查后重试。');return}joinRoom(roomId)}
 else if(a==='room-tab'){state.roomTab=b.dataset.tab;render()}
 else if(a==='attach-media'){mediaModal(b.dataset.scope)}
 else if(a==='confirm-media'){const media=state.pendingMedia;if(!media){toast('请先选择图片或视频。');return}const scope=b.dataset.scope,list=scope==='room'?currentRoom().messages:currentGroup().messages;list.push({id:'msg-'+state.nextId++,user:me,time:timeNow(),text:document.getElementById('media-caption').value.trim(),media});state.pendingMedia=null;closeModal();render();scrollChatToBottom(scope);toast(`${media.type==='video'?'视频':'图片'}已发送到${scope==='room'?'房间':'群组'}（仅本地模拟）。`)}
 else if(a==='toggle-mute'){state.muted=!state.muted;const m=myMember(currentRoom());if(m)m.muted=state.muted;if(state.muted)state.speaking=false;render();toast(state.muted?'麦克风已静音，虚拟网络保持连接。':'麦克风已开启。')}
 else if(a==='toggle-deafen'){state.deafened=!state.deafened;render();toast(state.deafened?'已关闭接收，不影响其他成员。':'已恢复接收。')}
 else if(a==='leave-room'){openModal('离开当前房间？','将撤销本次语音、虚拟网络和设备活动资格，房间配置仍会保留。','<div class="modal-note">主动退出后重入不承诺原 IP；地址安全、可用且无冲突时会优先尝试恢复。</div>',`<button class="button" data-action="modal-close">继续游戏</button><button class="button danger" data-action="confirm-leave">离开房间</button>`)}
 else if(a==='confirm-leave'){leaveRoom()}
 else if(a==='audio-settings'){state.view='settings';state.settingsTab='voice';closeModal();render()}
 else if(a==='settings-tab'){state.settingsTab=b.dataset.tab;closeModal();render()}
 else if(a==='device-test'){toast('仅演示设备测试入口，未采集或播放真实音频。')}
 else if(a==='copy-ip'){try{await navigator.clipboard.writeText(b.dataset.ip);toast(`已复制 ${b.dataset.ip}，请在游戏中直接连接。`)}catch{toast(`请手动复制：${b.dataset.ip}`)}}
 else if(a==='invite-friend'){inviteModal(b.dataset.name)}
 else if(a==='confirm-invite'){const name=document.getElementById('invite-name').value,roomId=document.getElementById('invite-room').value;if(!name){toast('请先添加好友。');return}state.invites.push({name,roomId,status:'pending'});closeModal();toast(`已向 ${name} 发送组队邀请（模拟）。`)}
 else if(a==='friend-filter'){state.friendFilter=b.dataset.filter;render()}
 else if(a==='friend-profile'){const n=b.dataset.name,p=people[n];openModal(n,'玩家资料卡',`<div style="display:flex;align-items:center;gap:14px;margin-bottom:18px">${avatar(n)}<div><strong>${n}</strong><p style="color:var(--muted);font-size:12px;margin:5px 0">${p.id} · ${personStatus(n)}</p></div></div><div class="modal-note">共同群组：${groups.filter(g=>g.members.includes(n)&&g.members.includes(me)).map(g=>g.name).join('、')||'无'}<br>可复制账号 ID、邀请组队或删除好友；首版不提供好友私聊。</div>`,`<button class="button danger" data-action="remove-friend" data-name="${n}">删除好友</button><button class="button" data-action="copy-id" data-name="${n}">复制账号 ID</button><button class="button primary" data-action="invite-friend" data-name="${n}">邀请组队</button>`)}
 else if(a==='copy-id'){const id=people[b.dataset.name].id;try{await navigator.clipboard.writeText(id);toast(`账号 ID ${id} 已复制。`)}catch{toast(`账号 ID：${id}`)}}
 else if(a==='add-friend'){openModal('添加好友','通过已验证邮箱或账号 ID 搜索。','<div class="field"><label>邮箱 / 账号 ID</label><input id="friend-account" value="newplayer#1024"></div><div class="modal-note">重复申请不会创建重复关系；对方接受后才成为好友。</div>',`<button class="button" data-action="modal-close">取消</button><button class="button primary" data-action="confirm-add-friend">发送申请</button>`)}
 else if(a==='confirm-add-friend'){const id=document.getElementById('friend-account').value.trim();if(!id)return;if(!state.outgoingRequests.includes(id))state.outgoingRequests.push(id);closeModal();toast(`已向 ${id} 发送好友申请（模拟）。`)}
 else if(a==='friend-requests'){openModal('待处理申请','接受或拒绝好友申请。',`${state.incomingRequests.map(n=>`<div class="friend-row" style="padding-left:0;padding-right:0">${avatar(n)}<div class="friend-copy"><strong>${n}</strong><small>希望添加你为好友</small></div><button class="button primary small" data-action="accept-request" data-name="${n}">接受</button><button class="button small" data-action="reject-request" data-name="${n}">拒绝</button></div>`).join('')||'<div class="empty-state">暂无待处理申请</div>'}<div class="modal-note">发出的申请：${state.outgoingRequests.join('、')||'无'}</div>`)}
 else if(a==='accept-request'){const n=b.dataset.name;state.incomingRequests=state.incomingRequests.filter(x=>x!==n);if(!state.friends.includes(n))state.friends.push(n);closeModal();render();toast(`已接受 ${n} 的好友申请，不会自动授予群权限。`)}
 else if(a==='reject-request'){state.incomingRequests=state.incomingRequests.filter(n=>n!==b.dataset.name);closeModal();render();toast('已拒绝好友申请。')}
 else if(a==='remove-friend'){const n=b.dataset.name;openModal(`删除好友 ${n}？`,'删除后不再显示对方在线与房间状态，不会自动退出共同群组。','',`<button class="button" data-action="modal-close">取消</button><button class="button danger" data-action="confirm-remove-friend" data-name="${n}">确认删除</button>`)}
 else if(a==='confirm-remove-friend'){state.friends=state.friends.filter(n=>n!==b.dataset.name);closeModal();render();toast('好友已删除。')}
 else if(a==='open-group'){state.groupId=b.dataset.group;state.view='groupChat';render()}
 else if(a==='create-group'){openModal('创建私密群组','不会出现在公开搜索，只通过邀请加入。','<div class="field"><label>群名称</label><input id="new-group-name" placeholder="给朋友们的小窝起个名字"></div><div class="field"><label>简介</label><textarea id="new-group-desc" placeholder="这个群用来做什么？"></textarea></div>',`<button class="button" data-action="modal-close">取消</button><button class="button primary" data-action="confirm-create-group">创建群组</button>`)}
 else if(a==='confirm-create-group'){const name=document.getElementById('new-group-name').value.trim();if(!name){toast('请填写群名称。');return}const id='group-'+state.nextId++,desc=document.getElementById('new-group-desc').value.trim();groups.push({id,name,desc,icon:name[0],members:[me],roomIds:[],messages:[]});state.groupId=id;state.view='groupChat';closeModal();render();toast('私密群组已创建（模拟）。')}
 else if(a==='group-manage'){groupManageModal()}
 else if(a==='manage-members'){openModal('成员与角色','普通成员可邀请；仅群主与管理员可撤销待接受邀请。','<div class="modal-note">移出成员会立即撤销后续群同步、语音、网络、恢复和设备活动资格。房主退群或账号失效时由群主接管，普通离线不触发接管。</div><div class="field" style="margin-top:16px"><label>邀请好友</label><select id="group-invite-name">'+state.friends.filter(n=>!currentGroup().members.includes(n)).map(n=>`<option>${n}</option>`).join('')+'</select></div>',`<button class="button" data-action="modal-close">关闭</button><button class="button primary" data-action="confirm-member-invite">发送邀请</button>`)}
 else if(a==='confirm-member-invite'){const n=document.getElementById('group-invite-name')?.value;if(n)state.invites.push({name:n,groupId:state.groupId,status:'pending'});closeModal();toast(n?`已向 ${n} 发送群组邀请（模拟）。`:'暂无可邀请好友。')}
 else if(a==='audit'){if(!canModerate()){toast('当前身份无权查看管理记录。');return}openModal('只读管理记录','仅当前群主和管理员可见，不包含任何秘密。','<div class="table-wrap"><table style="width:100%;border-collapse:collapse;font-size:12px"><tr><th align="left">操作者</th><th align="left">操作</th><th align="left">结果</th></tr><tr><td>林墨</td><td>修改房间开放状态</td><td>成功</td></tr><tr><td>阿岚</td><td>撤销待接受邀请</td><td>成功</td></tr></table></div>',`<button class="button primary" data-action="modal-close">关闭</button>`)}
 else if(a==='owner-actions'){if(state.role!=='owner')return;openModal('群主治理与危险操作','转让被接受前原群主不变；退出前必须转让或解散。','<div class="modal-note">结束活动会清退成员但保留房间；删除房间或解散群组为终态，全部会话与恢复终止。</div>',`<button class="button" data-action="transfer-owner">转让群主</button><button class="button danger" data-action="dissolve-group">解散群组</button>`)}
 else if(a==='transfer-owner'){closeModal();toast('转让请求已发送，等待指定成员接受。')}
 else if(a==='dissolve-group'){closeModal();toast('危险操作需再次人工确认；本原型未修改数据。')}
 else if(a==='room-settings'){roomSettingsModal()}
 else if(a==='pause-room'){const r=currentRoom();r.open=!r.open;closeModal();render();toast(r.open?'房间已重新开放。':'房间已暂停加入，现有成员未受影响。')}
 else if(a==='end-room'){openModal('结束当前活动？','将清退所有成员并终止语音与网络，房间配置和开放状态保留。','',`<button class="button" data-action="modal-close">取消</button><button class="button danger" data-action="confirm-end-room">确认结束</button>`)}
 else if(a==='confirm-end-room'){currentRoom().members=[];leaveRoom();toast('活动已结束，房间配置仍保留。')}
 else if(a==='save-room'){const r=currentRoom(),name=document.getElementById('edit-room-name').value.trim();if(!name){toast('房间名称不能为空。');return}r.name=name;r.game=document.getElementById('edit-room-game').value.trim()||'未指定游戏';r.host=document.getElementById('edit-room-host').value;closeModal();render();toast('房间配置已保存，列表已同步。')}
 else if(a==='player-settings'){const n=b.dataset.name,vol=state.memberVolumes[n]??70;openModal(`${esc(n)} · 语音`,'成员音量只影响本地接收。',`<div class="field"><label>成员音量 · <span id="member-volume-label">${vol}</span>%</label><input type="range" min="0" max="100" value="${vol}" data-input="member-volume" data-name="${n}"></div><div class="modal-note">被踢出房间不等于封禁；如无其他失权，可按当前规则重入。</div>`,`<button class="button primary" data-action="modal-close">完成</button>`)}
 else if(a==='delete-message'){openModal('删除这条消息？','删除后原位置保留提示；管理员代删会记入只读管理记录。','',`<button class="button" data-action="modal-close">取消</button><button class="button danger" data-action="confirm-delete-message" data-scope="${b.dataset.scope}" data-id="${b.dataset.id}">确认删除</button>`)}
 else if(a==='confirm-delete-message'){const list=b.dataset.scope==='room'?currentRoom().messages:currentGroup().messages,m=list.find(m=>m.id===b.dataset.id);if(m){m.deleted=true;m.text=''}closeModal();render();toast('消息已删除。')}
 else if(a==='account-settings'||a==='profile'){state.view='settings';state.settingsTab='account';closeModal();render()}
 else if(a==='device-transfer'){openModal('转移活动设备？','预检通过后原子替换当前设备；旧设备活动资格立即失效。','<div class="modal-note">本原型仅演示确认流程，不会执行真实设备转移。</div>',`<button class="button" data-action="modal-close">取消</button><button class="button primary" data-action="confirm-device-transfer">确认转移</button>`)}
 else if(a==='confirm-device-transfer'){leaveRoom();toast('模拟活动已转移至另一台电脑，此电脑已退出房间。')}
 else if(a==='support-matrix'){state.view='settings';state.settingsTab='support';closeModal();render()}
 else if(a==='help'||a==='network-help'){helpModal(a==='network-help')}
 else if(a==='network-retry'||a==='voice-retry'){const key=a==='network-retry'?'network':'voice';state[key]='retrying';render();setTimeout(()=>{state[key]='connected';render()},600)}
 else if(a==='toggle-setting'){state.settings[b.dataset.setting]=!state.settings[b.dataset.setting];render()}
 else if(a==='logout'){const r=currentRoom();openModal('退出登录？','确认后才会退出当前账号并返回登录页。',`<div class="modal-note">${state.joined&&r?`你正在「${esc(r.name)}」中，退出将离开房间并断开语音与虚拟局域网。<br>`:''}群组、房间和已发送消息不会因退出登录而删除。</div>`,`<button class="button" data-action="modal-close">取消</button><button class="button danger" data-action="confirm-logout">确认退出</button>`)}
 else if(a==='confirm-logout'){if(state.joined)leaveRoom();state.authenticated=false;state.authMode='login';closeModal();render()}
 else if(a==='auth-mode'){state.authMode=b.dataset.mode;render()}
 else if(a==='login'){state.authenticated=true;state.view='lobby';render()}
 else if(a==='register'){state.authMode='verify';render()}
 else if(a==='verify'){state.authenticated=true;state.view='lobby';render();toast('模拟邮箱验证完成。')}
 else if(a==='forgot'){state.authMode='login';render();toast('模拟重置邮件已发送。')}
 else if(a==='modal-close'){closeModal()}
 else if(a==='backdrop'){if(e.target===b)closeModal()}
});
document.addEventListener('input',e=>{if(e.target.dataset.input==='friend-search'){state.friendQuery=e.target.value;render();const input=document.querySelector('[data-input="friend-search"]');input.focus();input.setSelectionRange(input.value.length,input.value.length)}if(e.target.dataset.input==='volume'){state.volume=Number(e.target.value);document.getElementById('master-volume-label').textContent=`${state.volume}%`}if(e.target.dataset.input==='member-volume'){state.memberVolumes[e.target.dataset.name]=Number(e.target.value);document.getElementById('member-volume-label').textContent=e.target.value}if(e.target.dataset.input==='room-draft'&&state.roomId)state.drafts.room[state.roomId]=e.target.value;if(e.target.dataset.input==='group-draft'&&state.groupId)state.drafts.group[state.groupId]=e.target.value});
document.addEventListener('change',e=>{if(e.target.dataset.change==='role'){state.role=e.target.value;groupManageModal();toast('模拟身份已切换，仅用于权限走查。')}if(e.target.dataset.change==='input-device')state.settings.inputDevice=e.target.value;if(e.target.dataset.change==='output-device')state.settings.outputDevice=e.target.value;if(e.target.dataset.change==='media-file'){const file=e.target.files[0];if(!file)return;if(!/^image\/|^video\//.test(file.type)){state.pendingMedia=null;document.getElementById('media-preview').textContent='只支持图片或视频文件';return}state.pendingMedia={type:file.type.startsWith('video/')?'video':'image',url:URL.createObjectURL(file),name:file.name};document.getElementById('media-preview').innerHTML=mediaPreview(state.pendingMedia)}});
document.addEventListener('scroll',e=>{if(e.target.classList?.contains('chat-scroll')&&state.roomId)state.chatScroll.room[state.roomId]=e.target.scrollTop;if(e.target.classList?.contains('group-chat-body')&&state.groupId)state.chatScroll.group[state.groupId]=e.target.scrollTop},true);
document.addEventListener('submit',e=>{if(e.target.dataset.form==='room-message'){e.preventDefault();const input=document.getElementById('room-message-input'),text=input.value.trim(),id=state.roomId;if(text){currentRoom().messages.push({id:'msg-'+state.nextId++,user:me,time:timeNow(),text});state.drafts.room[id]='';render();scrollChatToBottom('room')}}if(e.target.dataset.form==='group-message'){e.preventDefault();const input=document.getElementById('group-message-input'),text=input.value.trim(),id=state.groupId;if(text){currentGroup().messages.push({id:'msg-'+state.nextId++,user:me,time:timeNow(),text});state.drafts.group[id]='';render();scrollChatToBottom('group')}}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.modal)closeModal()});
render();
